const input = $input.first().json;
const headers = input.headers || {};
const update = input.body || input;

if (update.update_id === undefined || update.update_id === null) {
  throw new Error('TELEGRAM_UPDATE_ID_REQUIRED: no fabricated idempotency key is allowed');
}
const updateId = update.update_id;
const webhookSecret = headers['x-telegram-bot-api-secret-token'] || null;

let message = update.message || null;
let isEdited = false;
let isCallback = false;
let callbackData = null;
if (update.edited_message) {
  message = update.edited_message;
  isEdited = true;
} else if (update.callback_query) {
  message = update.callback_query.message || null;
  isCallback = true;
  callbackData = update.callback_query.data || null;
}
if (!message) {
  return [{json:{ok:false,status:'ignored',update_id:updateId,error:{
    category:'validation',code:'UNSUPPORTED_UPDATE_TYPE',message_safe:'No actionable message in update'
  }}}];
}

const telegramUserId = update.callback_query?.from?.id ?? message.from?.id ?? null;
const telegramChatId = message.chat?.id ?? null;
if (telegramUserId === null || telegramChatId === null) {
  throw new Error('TELEGRAM_IDENTITY_REQUIRED');
}

const photos = Array.isArray(message.photo) ? message.photo : [];
const photo = photos.length ? photos[photos.length - 1] : null;
let media = null;
if (message.voice) {
  media = {media_kind:'audio', source_kind:'voice', ...message.voice, original_filename:null, mime_type:message.voice.mime_type || 'audio/ogg'};
} else if (message.audio) {
  media = {media_kind:'audio', source_kind:'audio', ...message.audio, original_filename:message.audio.file_name || null, mime_type:message.audio.mime_type || null};
} else if (message.document) {
  media = {media_kind:'document', source_kind:'document', ...message.document, original_filename:message.document.file_name || null, mime_type:message.document.mime_type || null};
} else if (photo) {
  media = {media_kind:'image', source_kind:'photo', ...photo, original_filename:null, mime_type:'image/jpeg'};
}
if (media) {
  media = {
    media_kind: media.media_kind,
    source_kind: media.source_kind,
    file_id: media.file_id || null,
    file_unique_id: media.file_unique_id || null,
    file_size: media.file_size ?? null,
    mime_type: media.mime_type || null,
    original_filename: media.original_filename || null,
    duration_ms: Number.isFinite(Number(media.duration)) ? Math.round(Number(media.duration) * 1000) : null
  };
  if (!media.file_id) throw new Error('TELEGRAM_MEDIA_FILE_ID_REQUIRED');
}

const text = message.text || message.caption || callbackData || '';
const rawDate = message.date || message.edit_date;
const capturedAt = rawDate ? new Date(rawDate * 1000).toISOString() : new Date().toISOString();

return [{json:{
  update_id:updateId,
  telegram_user_id:telegramUserId,
  telegram_chat_id:telegramChatId,
  message_id:message.message_id,
  text,
  is_edited:isEdited,
  is_callback:isCallback,
  callback_data:callbackData,
  captured_at:capturedAt,
  webhook_secret:webhookSecret,
  has_media:!!media,
  media
}}];

const rows = $input.all();
const norm = $('Normalize Telegram Update').first().json;
if (!rows.length || !rows[0].json?.user_id) {
  return [{json:{ok:false,status:'error',error:{
    category:'authorization',code:'UNAUTHORIZED_USER_OR_CHAT',message_safe:'Unauthorized Telegram sender or chat'
  }}}];
}
const user = rows[0].json;
const correlationId = 'corr_tg_' + crypto.randomUUID();
return [{json:{
  contract_version:'1.0',
  correlation_id:correlationId,
  user_id:user.user_id,
  source_channel:'telegram',
  captured_at:norm.captured_at,
  timezone:user.timezone || 'America/Argentina/Buenos_Aires',
  locale:user.locale || 'es-AR',
  assistant_name:user.assistant_name,
  update_id:norm.update_id,
  message_id:norm.message_id,
  telegram_chat_id:norm.telegram_chat_id,
  telegram_user_id:norm.telegram_user_id,
  text:norm.text,
  is_edited:norm.is_edited,
  is_callback:norm.is_callback,
  callback_data:norm.callback_data,
  has_media:norm.has_media,
  media:norm.media
}}];

const auth = $('Validate Auth and Security').first().json;
const ingRaw = $('Register Ingestion RPC').first().json.res;
const ing = typeof ingRaw === 'string' ? JSON.parse(ingRaw) : ingRaw;
const clarRows = $input.all();
if (ing.is_duplicate) {
  return [{json:{ok:true,status:'duplicate',correlation_id:auth.correlation_id,ingestion_id:ing.ingestion_id,target_route:'duplicate'}}];
}
let pendingClarification = null;
if (clarRows.length && clarRows[0].json?.id) pendingClarification = clarRows[0].json;
let targetRoute = auth.has_media ? 'process_media' : 'process_text';
const t = (auth.text || '').trim();
if (!auth.has_media && (t.startsWith('/start') || t.startsWith('/configuracion') || auth.is_callback)) {
  targetRoute = 'onboarding_and_config';
} else if (!auth.has_media && pendingClarification && !t.startsWith('?') && !t.toLowerCase().startsWith('no,') && t.length < 100) {
  targetRoute = 'resolve_clarification';
}
return [{json:{...auth,ingestion_id:ing.ingestion_id,target_route:targetRoute,pending_clarification:pendingClarification}}];
